package io.github.headlesshq.headlessmc.patcher.lwjgl.patched;

import io.github.headlesshq.headlessmc.reflection.ReflectionRegistered;
import io.quarkus.runtime.annotations.RegisterForReflection;

import java.util.Map;

/**
 * The lock file of the headlessmc-lwjgl release the patcher downloads, generated by {@code updatePatchedLwjgl}
 * in {@code build.gradle}.
 *
 * @param version the version of the headlessmc-lwjgl release.
 * @param jars the jars of the release, by their path relative to {@link PatchedLwjglPatcher#RESOURCES},
 *             e.g. {@code lwjgl3/lwjgl-glfw.jar} or {@code headlessmc-lwjgl-api.jar}.
 */
@RegisterForReflection
record PatchedLwjglLock(
    String version,
    Map<String, PatchedLwjglJar> jars
) implements ReflectionRegistered {

}
